set role service_role;
select test_assert(community_member('10000000-0000-4000-8000-000000000003','shop-a'),'active staff allowed');
select test_assert(not community_member('10000000-0000-4000-8000-000000000005','shop-a'),'inactive staff denied');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000004','shop-a','list')$q$,'COMMUNITY_FORBIDDEN');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000001','shop-b','list')$q$,'COMMUNITY_FORBIDDEN');
select community_dispatch('10000000-0000-4000-8000-000000000001','shop-a','create_post','{"id":"20000000-0000-4000-8000-000000000001","category":"operations","title":"예약금 질문 100%","body":"다른 매장과 운영 경험을 나눕니다.","newMedia":[{"mediaAssetId":"40000000-0000-4000-8000-000000000001","objectPath":"test/image.webp"}]}');
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','list')->'posts')=1,'another shop sees same post');
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','list','{"q":"%"}')->'posts')=1,'literal percent search');
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','list','{"q":"_"}')->'posts')=0,'literal underscore search');
select test_assert(not ((community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','list')->'posts'->0) ? 'author_id'),'public payload hides identity');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','delete_post','{"id":"20000000-0000-4000-8000-000000000001"}')$q$,'COMMUNITY_NOT_FOUND');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','update_post','{"id":"20000000-0000-4000-8000-000000000001"}')$q$,'COMMUNITY_NOT_FOUND');
select community_dispatch('10000000-0000-4000-8000-000000000003','shop-a','create_comment','{"id":"30000000-0000-4000-8000-000000000001","postId":"20000000-0000-4000-8000-000000000001","body":"직원도 참여합니다."}');
select community_dispatch('10000000-0000-4000-8000-000000000003','shop-a','create_comment','{"id":"30000000-0000-4000-8000-000000000001","postId":"20000000-0000-4000-8000-000000000001","body":"직원도 참여합니다."}');
select test_assert((select count(*)=1 from community_comments),'comment retry does not duplicate');
select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','block','{"targetType":"comment","targetId":"30000000-0000-4000-8000-000000000001"}');
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','detail','{"postId":"20000000-0000-4000-8000-000000000001"}')->'comments')=0,'blocked comments hidden');
select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','block','{"targetType":"post","targetId":"20000000-0000-4000-8000-000000000001"}');
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','list')->'posts')=0,'blocked post hidden');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','detail','{"postId":"20000000-0000-4000-8000-000000000001"}')$q$,'COMMUNITY_NOT_FOUND');
select test_assert(community_blocked('10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002'),'blocking is mutual');
select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','unblock',jsonb_build_object('id',id)) from community_blocks where user_id='10000000-0000-4000-8000-000000000002';
select community_dispatch('10000000-0000-4000-8000-000000000001','shop-a','update_post',jsonb_build_object('id',id,'category','knowledge','title','수정된 글','body','노하우를 공유합니다.','expectedUpdatedAt',updated_at,'retainedMediaIds',jsonb_build_array('40000000-0000-4000-8000-000000000001'))) from community_posts;
select test_assert((select category='knowledge' from community_posts),'own update works');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000001','shop-a','update_post','{"id":"20000000-0000-4000-8000-000000000001","expectedUpdatedAt":"2020-01-01T00:00:00Z"}')$q$,'COMMUNITY_CONFLICT');
select community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','report','{"targetType":"post","targetId":"20000000-0000-4000-8000-000000000001","reason":"검토가 필요합니다."}');
select test_assert(jsonb_array_length(community_moderate('fixture-admin','list')->'reports')=1,'moderator gets queue');
select community_moderate('fixture-admin','hide',id) from community_reports;
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000002','shop-b','list')->'posts')=0,'moderated post hidden');
select test_assert((select reviewed_by='fixture-admin' and reviewed_at is not null from community_reports),'moderation audited');
select test_assert(jsonb_array_length(community_dispatch('10000000-0000-4000-8000-000000000001','shop-a','delete_post','{"id":"20000000-0000-4000-8000-000000000001"}')->'removedPaths')=1,'delete returns photo cleanup paths');
select test_assert((select count(*)=0 from community_comments) and (select count(*)=0 from community_media_assets),'cascade deletes comments and photo rows');
reset role;
set role authenticated;
select test_reject('select * from community_posts','permission denied');
select test_reject($q$select community_dispatch('10000000-0000-4000-8000-000000000001','shop-a','list')$q$,'permission denied');
select test_reject($q$select community_moderate('spoofed-admin','list')$q$,'permission denied');
select test_reject($q$insert into storage.objects(bucket_id,name) values('community-images','injected.webp')$q$,'row-level security');
reset role;
select test_assert((select bool_and(relrowsecurity) from pg_class where relname like 'community_%' and relkind='r'),'all community tables have RLS');
select test_assert((select public=false from storage.buckets where id='community-images'),'private media bucket');
select test_assert((select count(*)=1 from community_media_deletions),'deleted photo retained in cleanup queue');
-- A provider-side account deletion must cascade content and still queue images.
set role service_role;
select community_dispatch('10000000-0000-4000-8000-000000000001','shop-a','create_post','{"id":"20000000-0000-4000-8000-000000000002","category":"lounge","title":"계정 삭제 검사","body":"계정 삭제 시 정리할 글입니다.","newMedia":[{"mediaAssetId":"40000000-0000-4000-8000-000000000002","objectPath":"test/account.webp"}]}');
reset role;
do $$ begin create role community_fixture_auth_delete; exception when duplicate_object then null; end $$;
grant usage on schema auth to community_fixture_auth_delete;
grant delete,select on auth.users to community_fixture_auth_delete;
set role community_fixture_auth_delete;
delete from auth.users where id='10000000-0000-4000-8000-000000000001';
reset role;
select test_assert((select count(*)=0 from community_posts),'account deletion removes authored posts');
select test_assert((select count(*)=2 from community_media_deletions),'account cascade queues media under restricted Auth role');
select 'COMMUNITY_SQL_PASS' as result;
